import json
import re
import pandas as pd
import pdfplumber

pdf_path = '/root/employees_backup.pdf'
xlsx_path = '/root/employees_current.xlsx'
output_path = '/root/diff_report.json'

# Extract tables from PDF
rows = []
cols = None

with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        tables = page.extract_tables()
        for table in tables:
            if not table:
                continue
            for row in table:
                if row is None:
                    continue
                cleaned = []
                for cell in row:
                    if isinstance(cell, str):
                        cell = cell.strip()
                    cleaned.append(cell)
                if all(cell in (None, '') for cell in cleaned):
                    continue
                if cleaned[0] == 'ID':
                    cols = cleaned
                    continue
                if cols is None:
                    # Skip until header found
                    continue
                if len(cleaned) < len(cols):
                    cleaned = cleaned + [None] * (len(cols) - len(cleaned))
                elif len(cleaned) > len(cols):
                    cleaned = cleaned[:len(cols)]
                rows.append(cleaned)

if cols is None:
    raise SystemExit('No header row found in PDF tables')

old_df = pd.DataFrame(rows, columns=cols)

# Drop rows without IDs
old_df = old_df[old_df['ID'].notna()]
old_df['ID'] = old_df['ID'].astype(str).str.strip()

# Normalize columns
expected_cols = ['ID', 'First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']
old_df = old_df[expected_cols]

# Clean numeric fields

def parse_int(value):
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return int(value)
    s = str(value).replace(',', '').strip()
    if s == '':
        return None
    return int(float(s))

def parse_float(value):
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = str(value).replace(',', '').strip()
    if s == '':
        return None
    return float(s)

old_df['Salary'] = old_df['Salary'].apply(parse_int)
old_df['Years'] = old_df['Years'].apply(parse_int)
old_df['Score'] = old_df['Score'].apply(parse_float)

# Load current Excel
new_df = pd.read_excel(xlsx_path, dtype={'ID': str})
new_df = new_df[expected_cols]
new_df['ID'] = new_df['ID'].astype(str).str.strip()

# Normalize numeric fields in new_df
new_df['Salary'] = new_df['Salary'].apply(parse_int)
new_df['Years'] = new_df['Years'].apply(parse_int)
new_df['Score'] = new_df['Score'].apply(parse_float)

# Build lookup dictionaries
old_records = old_df.set_index('ID').to_dict(orient='index')
new_records = new_df.set_index('ID').to_dict(orient='index')

old_ids = set(old_records.keys())
new_ids = set(new_records.keys())

# Deleted employees
deleted_employees = sorted(old_ids - new_ids)

# Modified employees
modified_employees = []
fields = [c for c in expected_cols if c != 'ID']

for emp_id in sorted(old_ids & new_ids):
    old_rec = old_records[emp_id]
    new_rec = new_records[emp_id]
    for field in fields:
        old_val = old_rec.get(field)
        new_val = new_rec.get(field)
        if pd.isna(old_val) and pd.isna(new_val):
            continue
        if old_val != new_val:
            modified_employees.append({
                'id': emp_id,
                'field': field,
                'old_value': old_val,
                'new_value': new_val,
            })

# Ensure sorted by ID, then field
modified_employees.sort(key=lambda x: (x['id'], x['field']))

report = {
    'deleted_employees': deleted_employees,
    'modified_employees': modified_employees,
}

with open(output_path, 'w', encoding='utf-8') as f:
    json.dump(report, f, indent=2)

print(f"Wrote {output_path} with {len(deleted_employees)} deletions and {len(modified_employees)} modifications")
